  0% { width: 0; opacity: 0; margin-left: 0; }
  10% { opacity: 1; }
  100% { 
    width: 330px; /* Din standard bredde */
    opacity: 1; 
    margin-left: 10px; 
  }
}

/* JUSTERING TIL MOBIL (Max-width 767px) */
