  @keyframes expandText {
    0% { width: 0; opacity: 0; margin-left: 0; }
    10% { opacity: 1; }
    100% { 
      /* Her kan du sætte en højere eller lavere værdi til mobil */
      width: 250px; 
      opacity: 1; 
      margin-left: 1px; 
    }
  }
}

