/* Slide styles */
.hero-ten-sektion__slide{

  /* Alle ikke-centrerede slides blødere i transition */
  .hero-ten-sektion__slide-img{
    transition: transform .4s ease, opacity .4s ease, filter .4s ease;
  }

  /* Naboerne til midten (30 deg) */
  &.is-prev .hero-ten-sektion__slide-img{
    transform: perspective(1500px) rotateY(30deg) scale(1);
    transform-origin: 100% 50% 0px;
    opacity: 0.85;
    will-change: transform;
  }

  &.is-next .hero-ten-sektion__slide-img{
    transform: perspective(1500px) rotateY(-30deg) scale(1);
    transform-origin: 0% 50% 0px;
    opacity: 0.85;
    will-change: transform;
  }

  /* De yderste slides (50 deg, større + lidt mere transparente/blødere) */
  &:has(+ .is-prev) .hero-ten-sektion__slide-img{
    transform: perspective(1500px) rotateY(50deg) scale(1.15);
    transform-origin: 100% 50% 0px;
    opacity: 0.6;
    will-change: transform;
  }

  .is-next + & .hero-ten-sektion__slide-img{
    transform: perspective(1500px) rotateY(-50deg) scale(1.15);
    transform-origin: 0% 50% 0px;
    opacity: 0.6;
    will-change: transform;
  }
}


