/* Sørg for, at overgangen er jævn for alle elementer */
.content-section-1-block {
    overflow: hidden; /* Sikrer at billedets zoom ikke skaber scrollbars */
}

/* Opdateret: Bruger de korrekte klasser for ikon og billede */
.content-section-1-block .content-section-1-ikon, content-section-1-img {
    transition: all 0.4s ease-in-out;
}

/* 1. Underline effekt på overskrift (.heading-ydelse) */
/* Opdateret: Bruger den korrekte klasse */
.content-section-1-block .content-section-1-heading {
    position: relative; 
    display: inline-block; 
}

/* Opretter selve linjen (underline) */
.content-section-1-block .content-section-1-heading::after {
    content: '';
    position: absolute;
    bottom: 4px;
    left: 0;
    width: 0; /* Starter med ingen bredde (usynlig) */
    height: 2px; /* Linjens tykkelse */
    background-color: #000; /* ERSTAT MED DIN ØNSKEDE FARVE */
    transition: width 0.4s ease-in-out; 
}

/* Linjen vises og strækker sig ved hover over hele blokken */
/* Opdateret: Bruger den korrekte klasse */
.content-section-1-block:hover .content-section-1-heading::after {
    width: 100%; 
}

/* 2. Rotér ikon (.ikon-ydelse) */
/* Opdateret: Bruger den korrekte klasse */
.content-section-1-block:hover .content-section-1-ikon {
    transform: rotate(45deg); /* Rotér ikonet -45 grader */
}

/* 3. Zoom effekt på billede (.image-ydelser) */
.content-section-1-block:hover{
  & .content-section-1-img{
    transform:scale(1.05)
  }
}

/*-- The root styles must go in the element of the structure with the name "Card team". --*/

/* Styles when the cursor is placed over the card the image is scaled 30% larger. */
.content-section-1-block:hover{
  & .content-section-1-box-img__avatar{
    transform:scale(1.1)
  }
}

