.ydelse-elleve-sektion__slider {
  .card-ydelse-elleve-sektion{
    /* Styles to make the entire card clickable and ensure that the top card is position relative */
    .card-ydelse-elleve-sektion__heading a:before {
      content: "";
      position: absolute;
      inset: 0;
      cursor: pointer;
    }

    /* Hover/focus kun på desktop (1025px+) */
    @media (min-width: 1025px) {
      &:hover, &:focus-within{
        .card-ydelse-elleve-sektion__overlay{
          opacity: 1;
        }
      }
    }

