/* Gør din hoved-block klar til positionering og skjul overflow */
.ydelse-4-bokse {
  position: relative;
  overflow: hidden; /* Meget vigtig! Skjuler teksten, når den er "udenfor" */
}

/* Opretter et pseudo-element, der fungerer som dit sorte hover-overlay */
.ydelse-4-bokse::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: #000; /* Baggrundsfarven ved hover */
  opacity: 0; /* Start helt gennemsigtig */
  transition: opacity 0.5s ease;
  z-index: 1; /* Lægger sig over baggrundsbillede, men under indhold */
}

/* Når man hover på .ydelse-4-bokse, gøres overlayet synligt */
.ydelse-4-bokse:hover::after {
  opacity: 0.65; /* Eller f.eks. 0.9 hvis den skal være let transparent */
}

/* Sørger for, at dit eksisterende indhold (heading) er over overlayet */
/* Juster evt. '.brxe-heading' hvis det er et andet element */
.ydelse-4-bokse > .header-sec {
  position: relative; /* Nødvendigt for z-index */
  z-index: 2;
  transition: opacity 0.3s ease, transform 0.5s ease; /* Tilføjet en pæn exit-animation */
}

/* * Styrer din tekst-block, der skal glide ind.
 * VIGTIGT: Giv din tekst-block CSS-klassen: .slide-in-content
 */
.ydelse-4-bokse .slide-in-text {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  padding: 0px 24px 24px 24px; /* Tilpas efter behov */
  color: #fff; /* Sørg for, at teksten er lys */

  /* Start-position: Skubbet 100% ned (ude af syne) */
  transform: translateY(100%);
  opacity: 0; /* Start usynlig */

  transition: transform 0.6s ease, opacity 0.5s ease;
  z-index: 3; /* Lægger sig øverst af alt */
}

/* Hover-tilstand: Kør tekstblokken ind og gør den synlig */
.ydelse-4-bokse:hover .slide-in-text {
  transform: translateY(0);
  opacity: 1;
}

/* VALGFRIT: Skjul den oprindelige heading, når den nye tekst kommer frem */
.ydelse-4-bokse:hover > .header-sec {
  transform: translateY(-25px); /* Giver en pæn "fade ud opad" effekt */
  opacity: 0;
}

